$ErrorActionPreference = "Stop"
$Root = Split-Path -Parent (Split-Path -Parent $MyInvocation.MyCommand.Path)

function Assert-True {
    param(
        [bool]$Condition,
        [string]$Message
    )
    if (-not $Condition) {
        throw $Message
    }
}

function Read-Text {
    param([string]$RelativePath)
    Get-Content -Raw -Encoding UTF8 -LiteralPath (Join-Path $Root $RelativePath)
}

foreach ($File in @("index.html", "work.html", "focus.html", "logs.html", "assets/app.js", "assets/apple-music-background.js", "assets/design-gallery.js", "assets/design-gallery.css", "assets/smooth-scroll.js", "assets/vendor/lenis.min.js", "assets/vendor/lenis.css", "assets/vendor/LENIS-LICENSE.txt", "assets/styles.css", "assets/favicon.png", "assets/avatar-fall-face-hd.png", "assets/fonts/yozai-notes.woff2", "assets/fonts/Yozai-OFL.txt", "images/work/work-01-final.jpg", "images/work/work-01-source.png", "content/photos.json", "content/design.json", "scripts/build-gallery.ps1", "scripts/cloudflare-build.mjs", "_headers", "robots.txt", "sitemap.xml", "404.html", "site.webmanifest", "package.json", "UPDATE_LOG.md", "RELEASE_LOG.md", "WORK_LOG.md")) {
    Assert-True (Test-Path -LiteralPath (Join-Path $Root $File)) "$File should exist"
}

$App = Read-Text "assets/app.js"
$AppleMusicBackground = Read-Text "assets/apple-music-background.js"
$SmoothScroll = Read-Text "assets/smooth-scroll.js"
$Css = Read-Text "assets/styles.css"
$Index = Read-Text "index.html"
$Work = Read-Text "work.html"
$Focus = Read-Text "focus.html"
$LogsHtml = Read-Text "logs.html"
$DesignJs = Read-Text "assets/design-gallery.js"
$DesignCss = Read-Text "assets/design-gallery.css"
$PhotosJson = Read-Text "content/photos.json"
$DesignJson = Read-Text "content/design.json"
$BuildGallery = Read-Text "scripts/build-gallery.ps1"
$CloudflareBuild = Read-Text "scripts/cloudflare-build.mjs"
$Headers = Read-Text "_headers"
$PackageJson = Read-Text "package.json"
$UpdateLog = Read-Text "UPDATE_LOG.md"
$ReleaseLog = Read-Text "RELEASE_LOG.md"
$WorkLog = Read-Text "WORK_LOG.md"
$AllText = "$Index`n$Work`n$Focus`n$App`n$Css`n$DesignCss"
$PhotoData = $PhotosJson | ConvertFrom-Json
$Photos = @($PhotoData.items)
$DesignData = $DesignJson | ConvertFrom-Json
$DesignLayers = @($DesignData.layers)

Assert-True ($Index -match "l4rxx") "home page should use the l4rxx name"
foreach ($Page in @($Index, $Work, $Focus, $LogsHtml)) {
    Assert-True ($Page -match 'assets/vendor/lenis\.css\?v=1\.3\.23' -and $Page -match 'assets/vendor/lenis\.min\.js\?v=1\.3\.23[\s\S]*assets/smooth-scroll\.js\?v=v160-design-gallery1[\s\S]*assets/app\.js\?v=v160-design-gallery1') "interactive pages should load the local Lenis runtime before site interactions"
}
Assert-True ($SmoothScroll -match 'lerp:\s*0\.045' -and $SmoothScroll -match 'wheelMultiplier:\s*0\.8' -and $SmoothScroll -match 'syncTouch:\s*true' -and $SmoothScroll -match 'touchMultiplier:\s*0\.8' -and $SmoothScroll -match 'overscroll:\s*false' -and $SmoothScroll -match 'prefers-reduced-motion:\s*reduce') "global scrolling should match the reference linear Lenis profile and respect reduced motion"
Assert-True ($Css -match 'html\s*\{[^}]*scrollbar-gutter:\s*stable') "global scroll locks should preserve the desktop scrollbar gutter so menus and lightboxes do not resize the page"
Assert-True ($SmoothScroll -match 'function applyDocumentScrollLock|const applyDocumentScrollLock' -and $SmoothScroll -match 'classList\.toggle\("l4rxx-scrollbar-lock", !nativeTouchScroll\.matches\)' -and $SmoothScroll -match 'nativeTouchScroll\.matches[\s\S]*document\.documentElement\.style\.overflow = "hidden"' -and $SmoothScroll -match 'window\.addEventListener\("scroll", restoreLockedDesktopScroll' -and $SmoothScroll -match 'window\.addEventListener\("wheel", preventLockedViewportWheel' -and $SmoothScroll -match 'document\.documentElement\.style\.overflow = savedHtmlOverflow' -and $Css -match 'html\.lenis\.lenis-stopped\.l4rxx-scrollbar-lock\s*\{[^}]*overflow-y:\s*scroll\s*!important') "desktop scroll locks should keep the real scrollbar visible while freezing its position, while touch devices retain overflow locking"
Assert-True ($DesignCss -match 'body\.design-lightbox-open\s*\{[^}]*overscroll-behavior:\s*none' -and $DesignCss -notmatch 'body\.design-lightbox-open\s*\{[^}]*overflow:\s*hidden') "Design lightbox should rely on the shared scroll lock without hiding the desktop scrollbar"
Assert-True ($SmoothScroll -match 'nativeTouchScroll = window\.matchMedia\("\(max-width: 768px\), \(hover: none\) and \(pointer: coarse\)"\)' -and $SmoothScroll -match 'nativeTouchScroll\.matches' -and $SmoothScroll -match 'nativeTouchScroll\.addEventListener\?\.\("change"' -and $Css -match '@media \(max-width: 768px\), \(hover: none\) and \(pointer: coarse\)[\s\S]*body\.site\s*\{[^}]*min-height:\s*calc\(100vh \+ 1px\)' -and $Css -match '@supports \(height: 100lvh\)[\s\S]*min-height:\s*calc\(100lvh \+ 1px\)' -and $App -match 'shell\.classList\.contains\("is-notes"\) && deltaY > 0') "touch devices should use native document scrolling so mobile Safari can collapse its browser chrome while upward notes swipes remain passive"
Assert-True ($Index -match 'data-nav-logs data-lenis-prevent' -and $Work -match 'data-nav-logs data-lenis-prevent' -and $Focus -match 'data-nav-logs data-lenis-prevent' -and $LogsHtml -match 'data-nav-logs data-lenis-prevent') "nested menu logs should retain independent native scrolling"
Assert-True ($Focus -match 'data-focus-image-toggle data-lenis-prevent-touch' -and $App -match 'indexGallery\.dataset\.lenisPrevent' -and $App -match 'focusIndexSmoothScroll' -and $App -match 'focusIndexSmoothScroll\.scrollTo' -and $App -match 'setWindowScrollPosition' -and $App -match 'lockSiteScroll' -and $App -match 'unlockSiteScroll' -and $SmoothScroll -match 'lockDepth' -and $SmoothScroll -match 'createNested') "focus gestures, nested INDEX scrolling, and programmatic positions should coordinate with global smooth scrolling"
Assert-True ($Index -match "data-language-switch") "home page should include a top-left language switch"
Assert-True ($Index -match "data-language-toggle") "language switch should use the final icon-only toggle"
Assert-True ($Index -match "language-globe" -and $Index -match "globe-axis" -and $Index -match "globe-lat") "language switch should use the globe symbol"
Assert-True ($Index -match "data-theme-toggle") "home page should include a top-right theme toggle"
Assert-True ($Index -match "theme-symbol" -and $Index -match '<i class="theme-core"></i>' -and $Index -match "theme-ray" -and $Index -match '<svg class="theme-moon"') "theme switch should use a hollow sun by day and a single-path moon by night"
Assert-True ($Index -match "data-i18n=`"social\.douyin`"") "Douyin/TikTok label should participate in language switching"
Assert-True ($AllText -match "nav-screen__log-link" -and $AllText -match "js-nav-logs-toggle" -and $AllText -match "visually-hidden[`"'][^>]*data-i18n=`"nav\.logs`"" -and $AllText -notmatch "nav-screen__log-label" -and $AllText -notmatch "nav-screen__log-link[`"'][^>]*href=`"logs\.html`"") "navigation menu should expose an icon-only bilingual logs button that opens logs inside the menu"
Assert-True ($App -match "initLanguageSwitch") "language switch should initialize from JavaScript"
Assert-True ($App -match 'LANGUAGE_STORAGE_KEY = "l4rxx-language"' -and $App -match 'localStorage\.getItem\(LANGUAGE_STORAGE_KEY\)' -and $App -match 'localStorage\.setItem\(LANGUAGE_STORAGE_KEY, next\)' -and $App -match 'legacySessionLanguage = sessionStorage\.getItem\(LANGUAGE_STORAGE_KEY\)' -and $App -match 'sessionStorage\.removeItem\(LANGUAGE_STORAGE_KEY\)' -and $App -match 'persistentLanguage \|\| legacySessionLanguage \|\| "en"') "first visits should start in English while an explicit language choice persists across later browser sessions"
Assert-True ($Index -match '<body[^>]*data-language="en"[^>]*data-lang="en"' -and $Work -match '<body[^>]*data-language="en"[^>]*data-lang="en"' -and $Focus -match '<body[^>]*data-language="en"[^>]*data-lang="en"' -and $LogsHtml -match '<body[^>]*data-language="en"[^>]*data-lang="en"') "interactive pages should expose English as their pre-JavaScript language state"
Assert-True ($Focus -match 'data-i18n="focus\.menuAbout">I tried to stop obsessing over settings and return to the record itself\.</p>') "focus menu should not flash Chinese before the English default is applied"
Assert-True ($App -match "initThemeSwitch") "theme switch should initialize from JavaScript"
Assert-True ($App -match "data-i18n") "language switch should update marked copy"
Assert-True ($App -match 'THEME_MODE_STORAGE_KEY = "l4rxx-theme-mode"' -and $App -match 'THEME_STORAGE_KEY = "l4rxx-theme"' -and $App -match "applySystemTheme") "theme switch should default to auto mode, migrate the legacy value, and react to later system theme changes"
Assert-True ($App -match 'const baseTheme = getAppliedTheme\(\)' -and $App -match 'themeMode = nextTheme;\s*persistThemeMode\(themeMode\);\s*applyTheme\(nextTheme, true\)' -and $App -match 'event\.matches \? "dark" : "light"' -and $App -match 'window\.addEventListener\("storage"' -and $App -match 'window\.addEventListener\("pageshow"') "manual theme input should invert the rendered theme and claim ownership before system, restored-page, or cross-tab updates can override it"
Assert-True ($App -match "prefers-color-scheme: dark") "theme should default to the system light/dark preference"
Assert-True ($App -match "is-theme-transitioning" -and $App -match "offsetHeight" -and $Css -match "is-theme-transitioning") "theme changes should use a temporary smooth color transition state"
Assert-True ($App -match "is-language-transitioning" -and $Css -match "is-language-transitioning") "language changes should crossfade text instead of hard-swapping copy"
Assert-True ($Css -match 'body\[data-theme="dark"\]') "site should define a full dark theme state"
Assert-True ($Css -match "text-shadow:[\s\S]*rgba\(235,\s*231,\s*223" -and $Css -match "body\[data-theme=`"dark`"\][\s\S]*\.brand-letter") "dark theme should add a restrained glow to key typography"
Assert-True ($App -match "social\.douyin`": `"TIKTOK`"" -and $App -match "social\.douyin`": `"\\u6296\\u97f3`"") "Douyin/TikTok label should switch between English and Chinese"
Assert-True ($Css -match "\.language-switch") "language switch should have source-style fixed positioning"
Assert-True ($Css -match "body::after\s*\{[^}]*height:\s*clamp\([^)]+\)" -and $Css -match "body::after\s*\{[^}]*z-index:\s*900" -and $Css -match "body::after\s*\{[^}]*backdrop-filter:\s*blur\(6px\)" -and $Css -match "body::after\s*\{[^}]*mask-image:\s*linear-gradient" -and $Css -match "\.symbol\s*\{[^}]*filter:\s*none" -and $Css -match "\.nav-toggle\s*\{[^}]*filter:\s*none" -and $Css -notmatch "\.language-switch::before|\.theme-toggle::before|\.nav-toggle::before") "top controls should use one shared fading edge haze without per-icon halos or visible button plates"
Assert-True ($Css -match "\.theme-core\s*\{[^}]*background-color:\s*transparent" -and $Css -notmatch "\.theme-toggle:hover \.theme-core\s*\{[^}]*background-color") "theme icon should remain hollow at rest and on hover"
Assert-True ($Css -match "\.theme-moon\s*\{[^}]*fill:\s*none;[^}]*stroke:\s*currentColor;[^}]*stroke-linecap:\s*round;[^}]*stroke-linejoin:\s*round" -and $Css -match 'body\[data-theme="dark"\] \.theme-moon\s*\{[^}]*opacity:\s*1') "night-theme moon should use a crisp hollow stroke instead of overlapping filled circles"
Assert-True ($Css -match "--theme-sun-ray-edge:\s*calc\(\(var\(--theme-sun-ray-length\) - var\(--theme-sun-core-size\)\) / 2\)") "day-theme sun ray gap should derive from the center-ring diameter"
Assert-True ($Css -match "\.theme-symbol \.theme-ray-a,[\s\S]*?transparent var\(--theme-sun-ray-edge\) calc\(100% - var\(--theme-sun-ray-edge\)\)") "day-theme sun rays should meet the hollow center ring"
Assert-True ($Css -match "--theme-sun-ray-length:\s*2\.36rem" -and $Css -match "--theme-moon-size:\s*2\.36rem" -and $Css -match "@media \(max-width:\s*768px\)[\s\S]*?\.theme-symbol\s*\{[^}]*--theme-sun-ray-length:\s*1\.86rem;[^}]*--theme-moon-size:\s*1\.86rem") "theme control should match the language globe diameter on desktop and mobile"
Assert-True (@($Index, $Work, $Focus, $LogsHtml).Where({ $_ -match '<i class="theme-core"></i>' -and $_ -match "theme-ray" -and $_ -match '<svg class="theme-moon"[^>]*>[\s\S]*?<path d="M12 3a6 6 0 0 0 9 9 9 9 0 1 1-9-9Z"></path>' -and $_ -notmatch "theme-eclipse|theme-lines-pop" }).Count -eq 4) "shared theme controls should retain the hollow sun and use the same clean moon path"
Assert-True ($AllText -match "https://www\.douyin\.com/user/self\?from_tab_name=main") "nav screen should link to Douyin"
Assert-True ($AllText -match "https://www\.instagram\.com/l4rxdx/") "nav screen should link to Instagram"
Assert-True ($Css -match "\.nav-screen__social") "nav social links should have a menu footer layout"
foreach ($Page in @($Index, $Work, $Focus, $LogsHtml)) {
    Assert-True ($Page -match 'data-copy-email="2664395883@qq\.com"' -and $Page -match 'data-copy-email-status' -and $Page -notmatch 'mailto:hello@l4rxx\.local') "every shared menu should copy the authorized public contact email instead of linking to the placeholder address"
}
Assert-True ($App -match 'initEmailCopy\(\)' -and $App -match 'navigator\.clipboard\.writeText' -and $App -match 'document\.execCommand\("copy"\)' -and $App -match 'selectEmailFallback' -and $App -match 'label\.textContent = copied \? languageCopy\[language\]\["contact\.copied"\] : email' -and $Css -match '\.nav-screen__copy-email\.is-copy-failed \[data-copy-email-label\]' -and $Headers -match '(?m)^/\*\r?$' -and $Headers -match 'Permissions-Policy:\s*clipboard-write=\(self\)') "the contact command should copy with two same-gesture paths, declare clipboard permission, and expose a selectable email fallback"
Assert-True ($Css -match "\.nav-screen__log-link" -and $Css -match "\.nav-screen__log-symbol" -and $Css -match "log-symbol__page" -and $Css -match "log-symbol__fold" -and $Css -match "log-symbol__line" -and $Css -notmatch "\.nav-screen__log-label" -and $AllText -notmatch "log-symbol__corner|log-symbol__mark|nav-screen__log-label") "logs entry should use an icon-only single-page document symbol in the menu"
Assert-True ($AllText -match "data-nav-logs" -and $AllText -match "data-nav-release-entries" -and $Css -match "is-nav-logs" -and $App -match "initNavLogsMode" -and $App -match "renderReleaseLogSurface") "logs icon should take over the existing Gaussian menu instead of navigating away"
Assert-True ($App -match "function setNavigationOpen\(open" -and $App -match "setNavigationOpen\(false, screen, toggle\)" -and $App -match "setNavLogsOpen\(false\)" -and $App -match "setNavLogsOpen\(!logsOpen\)") "top X should close the whole menu from logs mode while the lower-right logs icon toggles logs back to the menu"
Assert-True ($Css -notmatch "body\.is-nav-logs\s+\.nav-screen__log-link\s*\{[^}]*pointer-events:\s*none" -and $Css -notmatch "body\.is-nav-logs\s+\.nav-screen__log-link\s*\{[^}]*opacity:\s*0") "logs toggle should stay visible and clickable while the menu is showing release notes"
Assert-True ($Css -match "body\.is-theme-transitioning:not\(\.is-language-transitioning\) \.logs-page" -and $Css -match "body\.is-theme-transitioning:not\(\.is-language-transitioning\) \.nav-screen__logs") "theme changes should not trigger opacity or blur flicker on release-log copy"
Assert-True ($Css -notmatch "body\.is-theme-transitioning:not\(\.is-language-transitioning\) \.logs-page[\s\S]*?transition-property:\s*color" -and $Css -notmatch "body\.is-theme-transitioning:not\(\.is-language-transitioning\) \.nav-screen__logs[\s\S]*?transition-property:\s*color") "release-log copy should not run its own color transition on top of the body theme transition"
Assert-True ($Css -match "\.logs-shell\s*\{[\s\S]*color:\s*#0c0c0c[\s\S]*transition:\s*color \.46s" -and $Css -match "body\[data-theme=`"dark`"\] \.logs-shell\s*\{[\s\S]*color:\s*#ebe7df" -and $Css -notmatch "body\.is-theme-transitioning:not\(\.is-language-transitioning\) \.logs-shell\s*\{[\s\S]*transition:\s*none") "logs page should keep one concise explicit color transition layer for smooth theme changes"
Assert-True ($App -match "window\.setTimeout\(clearThemeTransition, 560\)" -and $App -notmatch "animateNavThemeColor|animateLogsThemeColor|logsThemeTransitionTimers" -and $Css -match "body\.is-theme-transitioning \.logs-shell[\s\S]*transition-duration:\s*\.46s") "theme switching should use one interruptible CSS transition instead of competing inline color animations"
Assert-True ($Css -match "body\.is-theme-transitioning \.logs-page::after" -and $Css -match "body\.is-theme-transitioning \.logs-shell" -and $Css -notmatch "body\[data-theme=`"dark`"\] \.logs-page::before") "release logs should share the global theme timing while their background photo remains unchanged"
Assert-True (@($Index, $Work, $Focus, $LogsHtml).Where({ $_ -match '<img src="assets/avatar-fall-face-hd\.png\?v=avatar-user1" alt="l4rxx avatar" class="nav-screen__avatar">' }).Count -eq 4) "the supplied transparent avatar should be wired into the menu on every page"
Assert-True ($Css -match "\.nav-screen__avatar[\s\S]*object-fit:\s*contain" -and $Css -match "body\[data-theme=`"dark`"\]\s+\.nav-screen__avatar" -and $Css -match "drop-shadow" -and $AllText -match "assets/avatar-fall-face-hd\.png\?v=avatar-user1") "menu avatar should use the supplied transparent line asset with an uncropped theme-aware silhouette shadow"
Assert-True ($AllText -match '<link rel="icon" type="image/png" href="assets/favicon\.png">') "all pages should use the avatar favicon"
Assert-True ($AllText -match '<link rel="apple-touch-icon" href="assets/favicon\.png">') "all pages should expose the avatar touch icon"
Assert-True ($AllText -match '<link rel="manifest" href="site\.webmanifest">') "all pages should expose the web manifest"
Assert-True ($AllText -match '<meta property="og:title" content="l4rxx">') "all pages should include share preview metadata"
Assert-True ($Focus -match "rel") "focus page should support rel query navigation"
Assert-True ($App -match "new URLSearchParams\(window\.location\.search\)") "focus page should parse URL query params"

Assert-True ($App -match 'PHOTO_MANIFEST_VERSION = \(\(\) => \{' -and $App -match 'searchParams\.get\("v"\)' -and $App -match 'const isLocalPreview' -and $App -match 'fetch\(manifestUrl, \{ cache: isLocalPreview \? "no-cache" : "default" \}\)') "gallery data should inherit the app asset version and revalidate on local networks"
Assert-True ($App -notmatch 'const\s+photos\s*=\s*\[') "gallery photos should not be hard-coded in app.js"

$ImageSources = @($Photos | ForEach-Object { $_.full; $_.thumb })
Assert-True ($Photos.Count -eq 58) "gallery should include 58 local images after appending the latest photos"
Assert-True ($PhotosJson -notmatch "DSC00081|001-dsc00081|zz-douyin-follow-meme") "excluded utility images should not appear in gallery data"
Assert-True ($PhotosJson -match "R0010392|DSC02934-2|DSC01690|1\.1\.2_1\.1\.2|R0011406|winter-sweet|makeup-flash|pastel-beach|daisies-bee|seagulls-plaza|station-crossing|park-bench-canopy|fallen-leaf-shadow|sunlit-pavilion|rainbow-umbrella-road|blue-horizon-ship") "newly added photos should appear in gallery data"
