$LatestPhoto = $Photos | Where-Object { $_.id -eq 44 } | Select-Object -First 1
$LatestLocationCn = -join ([char]0x5E7F, [char]0x5DDE, [char]0x20, [char]0x534E, [char]0x5357, [char]0x690D, [char]0x7269, [char]0x56ED)
Assert-True ($LatestPhoto.full -eq "images/web/044-r0011529.jpg" -and -not [string]::IsNullOrWhiteSpace($LatestPhoto.noteCn) -and $LatestPhoto.note -eq $LatestPhoto.noteCn -and $LatestPhoto.noteEn -match "taking photos from this angle" -and $LatestPhoto.locationCn -eq $LatestLocationCn -and $LatestPhoto.locationEn -eq "Guangzhou South China Botanical Garden") "the latest cat photo should preserve its bilingual note and botanical garden location"
$WaterPhoto = $Photos | Where-Object { $_.id -eq 45 } | Select-Object -First 1
